css:
.backdrop {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  padding: 24px;
  background-image: linear-gradient(135deg, #f97316, #7c3aed);
  font-family: system-ui, sans-serif;
}

.panel {
  padding: 16px;
  border-radius: 8px;
  color: #18181b;
}

.panel h3 {
  margin: 0 0 4px;
}

.panel p {
  margin: 0;
}

.faded {
  background-color: #ffffff;
  opacity: 0.6;
}

.tinted {
  background-color: rgb(255 255 255 / 0.6);
}
